using NexaStation.Customization.Models;
using NexaStation.Infrastructure.Persistence;
using Xunit;

namespace NexaStation.Infrastructure.Tests;

public sealed class CustomizationPersistenceTests
{
    [Fact]public async Task DashboardAndRowsRoundTrip(){await using PersistenceTests.TestDb db=await PersistenceTests.TestDb.Create();SqliteCustomizationStore store=new(db.Factory);DateTime now=DateTime.UtcNow;DashboardConfiguration dashboard=new("dashboard","modern-dashboard","Default",true,true,DashboardCardDensity.Balanced,18,true,true,now,now);DashboardRowConfiguration row=new("row",dashboard.Id,"favorites","Favorites",DashboardRowType.BuiltIn,null,0,true,12,CardStyle.Wide,CardSize.Medium,true,true,true,false,now,now);await store.SaveDashboardAsync(dashboard);await store.ReplaceRowsAsync(dashboard.Id,[row]);Assert.Equal(dashboard,await store.GetDashboardAsync("modern-dashboard"));Assert.Equal(row,(await store.GetRowsAsync(dashboard.Id))[0]);}
    [Fact]public async Task PinsCollectionsAndRulesRoundTrip(){await using PersistenceTests.TestDb db=await PersistenceTests.TestDb.Create();SqliteCustomizationStore store=new(db.Factory);DateTime now=DateTime.UtcNow;await store.SavePinAsync(new("pin",PinTargetType.LibraryItem,"item",PinLocation.Home,null,0,now,now));CollectionDefinition collection=new("collection","Favorites",null,CollectionType.Smart,null,null,null,0,false,SmartRuleMatchMode.MatchAll,now,now);await store.SaveCollectionAsync(collection);await store.SaveCollectionItemAsync(new(collection.Id,CollectionTargetType.LibraryItem,"item",0,now));SmartCollectionRule rule=new("rule",collection.Id,0,SmartRuleField.Favorite,SmartRuleOperator.IsTrue,null,0,now,now);await store.ReplaceRulesAsync(collection.Id,[rule]);Assert.Single(await store.GetPinsAsync(PinLocation.Home));Assert.Equal(collection,await store.GetCollectionAsync(collection.Id));Assert.Single(await store.GetCollectionItemsAsync(collection.Id));Assert.Equal(rule,(await store.GetRulesAsync(collection.Id))[0]);}
    [Fact]public async Task CustomThemeRoundTrips(){await using PersistenceTests.TestDb db=await PersistenceTests.TestDb.Create();SqliteCustomizationStore store=new(db.Factory);ThemeDefinition theme=new("custom","Custom","Local",ThemeType.Custom,"#123456","#654321",new(BackgroundType.Image,@"C:\managed\background.png",BackgroundStretch.Fit,8,.4,.9,true),CardShape.Soft,.8,true,AnimationIntensity.Low,"nexa-soft",false,"1","Local user","0.7");await store.SaveThemeAsync(theme);Assert.Equal(theme,(await store.GetCustomThemesAsync())[0]);}
    [Fact]public async Task SnapshotApplyReplacesOnlyInterfaceTables(){await using PersistenceTests.TestDb db=await PersistenceTests.TestDb.Create();SqliteCustomizationStore store=new(db.Factory);DateTime now=DateTime.UtcNow;DashboardConfiguration dashboard=new("dashboard","modern-dashboard","Imported",true,true,DashboardCardDensity.Dense,10,true,true,now,now);InterfaceConfigurationSnapshot snapshot=new(1,now,"modern-dashboard",[dashboard],[],[],[],[],[],"nexa-dark",null,"silent",0,new(VisualPerformancePreset.Minimal,false,0,AnimationIntensity.None,false,55,32,512,true,true,true,12,true));await store.ApplySnapshotAsync(snapshot);Assert.Equal("Imported",(await store.GetDashboardAsync("modern-dashboard"))?.Name);Assert.Equal(74,await db.Scalar("SELECT COUNT(*) FROM SchemaMigrations"));}
}
